-- All accounts, OAuth payloads and email sends are synthetic and rolled back. No provider calls.
begin;
select set_config('qa.owner',gen_random_uuid()::text,true),set_config('qa.other',gen_random_uuid()::text,true),set_config('qa.job',gen_random_uuid()::text,true),set_config('qa.otherjob',gen_random_uuid()::text,true),set_config('qa.mailbox',gen_random_uuid()::text,true),set_config('qa.othermailbox',gen_random_uuid()::text,true),set_config('qa.scout',gen_random_uuid()::text,true);
insert into auth.users(id,email)values(current_setting('qa.owner')::uuid,'upwork-fixture-'||current_setting('qa.owner')||'@example.test'),(current_setting('qa.other')::uuid,'upwork-fixture-'||current_setting('qa.other')||'@example.test');
insert into public.mailboxes(id,owner_id,email,provider,status)values(current_setting('qa.mailbox')::uuid,current_setting('qa.owner')::uuid,'sender@fixture.example','custom','connected'),(current_setting('qa.othermailbox')::uuid,current_setting('qa.other')::uuid,'other@fixture.example','custom','connected');
insert into public.upwork_jobs(id,owner_id,external_id,job)values(current_setting('qa.job')::uuid,current_setting('qa.owner')::uuid,'fixture-job','{"title":"Fixture job"}'),(current_setting('qa.otherjob')::uuid,current_setting('qa.other')::uuid,'fixture-job','{"title":"Other private job"}');
insert into public.upwork_scouts(id,owner_id,job_id,status,report)values(current_setting('qa.scout')::uuid,current_setting('qa.owner')::uuid,current_setting('qa.job')::uuid,'researching','{"contacts":[{"kind":"email","value":"public@fixture.example"}]}');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
do $$declare owner uuid:=current_setting('qa.owner')::uuid;other uuid:=current_setting('qa.other')::uuid;v jsonb;app uuid;sid uuid;
begin
 insert into public.upwork_connections(owner_id)values(owner),(other);
 perform public.aisas_upwork_credentials(owner,'{"access_token":"fixture-access","refresh_token":"fixture-refresh"}');
 if public.aisas_upwork_credentials(owner)->>'access_token'<>'fixture-access' then raise exception 'Encrypted token round trip failed';end if;
 if public.aisas_upwork_credentials(other) is not null then raise exception 'Token crossed owners';end if;
 if not public.aisas_upwork_refresh_lock(owner) or public.aisas_upwork_refresh_lock(owner) then raise exception 'Concurrent refresh lock failed';end if;
 perform public.aisas_upwork_refresh_lock(owner,true);
 perform public.aisas_upwork_credentials(owner,'{"access_token":"fixture-new","refresh_token":"fixture-refresh"}',false,'fixture-access');
 begin perform public.aisas_upwork_credentials(owner,'{"access_token":"stale"}',false,'fixture-access');raise exception 'Stale refresh replaced fresh tokens';exception when raise_exception then if sqlerrm<>'Upwork connection changed; reconnect' then raise;end if;end;
 perform public.aisas_upwork_oauth('fixture-state',owner,'fixture-verifier','fixture-client');
 v:=public.aisas_upwork_oauth('fixture-state');if v->>'owner_id'<>owner::text or v->>'verifier'<>'fixture-verifier' then raise exception 'OAuth state owner mismatch';end if;
 if public.aisas_upwork_oauth('fixture-state') is not null then raise exception 'OAuth state replayed';end if;
 perform public.aisas_upwork_oauth('expired-state',owner,'fixture-verifier','fixture-client');
 update aisas_private.upwork_oauth_states set expires_at=now()-interval '1 second' where owner_id=owner;
 if public.aisas_upwork_oauth('expired-state') is not null then raise exception 'Expired state consumed';end if;
 v:=public.aisas_upwork_claim_scout(owner,current_setting('qa.scout')::uuid);
 if v is null or public.aisas_upwork_claim_scout(owner,current_setting('qa.scout')::uuid) is not null or public.aisas_upwork_claim_scout(other,current_setting('qa.scout')::uuid) is not null then raise exception 'Scout claim crossed owners or duplicated';end if;
 update public.upwork_scouts set status='completed',claim_token=null,claimed_until=null where id=current_setting('qa.scout')::uuid;
 begin perform public.aisas_upwork_reserve_application(owner,current_setting('qa.job')::uuid,current_setting('qa.othermailbox')::uuid,'public@fixture.example','Subject','Body');raise exception 'Other mailbox allowed';exception when raise_exception then if sqlerrm<>'Connect a sending mailbox' then raise;end if;end;
 begin perform public.aisas_upwork_reserve_application(owner,current_setting('qa.job')::uuid,current_setting('qa.mailbox')::uuid,'guessed@fixture.example','Subject','Body');raise exception 'Guessed email allowed';exception when raise_exception then if sqlerrm<>'Use a researched email address' then raise;end if;end;
 app:=public.aisas_upwork_reserve_application(owner,current_setting('qa.job')::uuid,current_setting('qa.mailbox')::uuid,'public@fixture.example','Subject','Body');
 if app is null or public.aisas_upwork_reserve_application(owner,current_setting('qa.job')::uuid,current_setting('qa.mailbox')::uuid,'public@fixture.example','Subject','Body') is not null then raise exception 'Duplicate application sent';end if;
 update public.upwork_applications set status='failed' where id=app;
 if public.aisas_upwork_reserve_application(owner,current_setting('qa.job')::uuid,current_setting('qa.mailbox')::uuid,'public@fixture.example','Subject','Body')<>app then raise exception 'Known rejection not retryable';end if;
 update public.upwork_applications set status='uncertain' where id=app;
 if public.aisas_upwork_reserve_application(owner,current_setting('qa.job')::uuid,current_setting('qa.mailbox')::uuid,'public@fixture.example','Subject','Body') is not null then raise exception 'Unknown send retried';end if;
 update public.upwork_applications set status='sent' where id=app;
 if public.aisas_upwork_reserve_application(owner,current_setting('qa.job')::uuid,current_setting('qa.mailbox')::uuid,'public@fixture.example','Subject','Body') is not null then raise exception 'Accepted send retried';end if;
 for n in 1..50 loop if not public.aisas_upwork_usage(owner,'upwork-send') then raise exception 'Usage rejected too early';end if;end loop;
 if public.aisas_upwork_usage(owner,'upwork-send') then raise exception 'Usage cap ignored';end if;
 select secret_id into sid from aisas_private.upwork_credentials where owner_id=owner;
 perform public.aisas_upwork_oauth('pending-state',owner,'fixture-verifier','fixture-client');
 perform public.aisas_upwork_credentials(owner,null,true);
 if exists(select 1 from vault.secrets where id=sid) or exists(select 1 from aisas_private.upwork_oauth_states where owner_id=owner) then raise exception 'Disconnect retained secret or state';end if;
 if not exists(select 1 from public.upwork_applications where id=app) then raise exception 'Disconnect erased history';end if;
end $$;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('qa.owner'),'role','authenticated')::text,true);
do $$begin
 if (select count(*) from public.upwork_jobs)<>1 or (select count(*) from public.upwork_scouts)<>1 or (select count(*) from public.upwork_applications)<>1 then raise exception 'Owner RLS failed';end if;
 begin update public.upwork_applications set status='sent';raise exception 'Client forged send';exception when insufficient_privilege then null;end;
 begin insert into public.upwork_jobs(owner_id,external_id,job)values(auth.uid(),'forged','{}');raise exception 'Client forged jobs';exception when insufficient_privilege then null;end;
 begin perform public.aisas_upwork_credentials(auth.uid());raise exception 'Client read tokens';exception when insufficient_privilege then null;end;
 begin perform public.aisas_upwork_claim_scout(auth.uid(),current_setting('qa.scout')::uuid);raise exception 'Client bypassed scout worker';exception when insufficient_privilege then null;end;
 begin perform public.aisas_upwork_config();raise exception 'Client read configuration';exception when insufficient_privilege then null;end;
 begin perform 1 from aisas_private.upwork_credentials;raise exception 'Private token table accessible';exception when insufficient_privilege then null;end;
end $$;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('qa.other'),'role','authenticated')::text,true);
do $$begin
 if (select count(*) from public.upwork_jobs)<>1 or exists(select 1 from public.upwork_scouts) or exists(select 1 from public.upwork_applications) then raise exception 'Other owner data exposed';end if;
end $$;
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
do $$begin begin perform 1 from public.upwork_jobs;raise exception 'Anonymous read jobs';exception when insufficient_privilege then null;end;end $$;
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
do $$declare sid uuid;begin
 perform public.aisas_upwork_credentials(current_setting('qa.other')::uuid,'{"access_token":"deletion-fixture"}');
 select secret_id into sid from aisas_private.upwork_credentials where owner_id=current_setting('qa.other')::uuid;
 delete from auth.users where id=current_setting('qa.other')::uuid;
 if exists(select 1 from vault.secrets where id=sid) or exists(select 1 from public.upwork_jobs where owner_id=current_setting('qa.other')::uuid) then raise exception 'Account deletion retained Upwork data';end if;
end $$;
select 'PASS: Upwork RLS, Vault lifecycle, state replay protection, refresh locks, scout claims, owned mailbox checks, application idempotency and quotas' as result;
rollback;
